#!/bin/bash
# Create wst.aucfans.com as a new site on this server (additive; does not touch ayet or l1).
echo "== creating web root =="
mkdir -p /var/www/wst.aucfans.com

# --- homepage (decoded from gzip+base64) ---
rm -f /tmp/_wst.b64
printf '%s' '' >> /tmp/_wst.b64
