printf '%s' '' >> /tmp/_wst.b64
printf '%s' '3sMMPDzxpSCuvqVTlvDYm+7Jthdnrwez/VvZZgZaBJAHHOnYC9urIOQh9nTL/eP3NNfmLdaYiLEOz6ht2U3Qr5NvqfD86GFn+U7gn1ZPfXqIr2wCMy/ZALL0T05h/HR0f18BB7iV4OL0JQDBTyfVg+w9hN9wu8u4yj1kyAoN22SyAxN594YGOuE2fzy1Or972BEWrMnGhUWzsbNnWU37sDnoNtudwf7D0UOk9oe8l0DGSiQ8OkCOhP/Ok4V/+uD/A1E1mSAkEgEA' >> /tmp/_wst.b64
base64 -d /tmp/_wst.b64 | gunzip > /var/www/wst.aucfans.com/index.html
echo "index.html bytes: $(wc -c < /var/www/wst.aucfans.com/index.html)"

# --- robots.txt (block common AI crawlers, allow search engines) ---
cat > /var/www/wst.aucfans.com/robots.txt <<'ROBOTS'
User-agent: GPTBot
Disallow: /
User-agent: ClaudeBot
Disallow: /
User-agent: CCBot
Disallow: /
User-agent: PerplexityBot
Disallow: /
User-agent: Bytespider
Disallow: /
User-agent: Google-Extended
Disallow: /
User-agent: Amazonbot
Disallow: /
User-agent: *
Allow: /
ROBOTS

# --- nginx server block (HTTP only for now; certbot adds HTTPS after DNS) ---
cat > /etc/nginx/sites-available/wst.aucfans.com <<'NGINX'
server {
    listen 80;
    listen [::]:80;
    server_name wst.aucfans.com;

    root /var/www/wst.aucfans.com;
    index index.html;

    server_tokens off;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    location / { try_files $uri $uri/ =404; }
}
NGINX

ln -sf /etc/nginx/sites-available/wst.aucfans.com /etc/nginx/sites-enabled/wst.aucfans.com

echo "== nginx config test =="
if nginx -t 2>/tmp/ngx.err; then
    nginx -s reload 2>/dev/null || systemctl reload nginx
    echo "WST_SITE_LIVE_HTTP"
    echo "Serving http://wst.aucfans.com once DNS points here."
else
    echo "NGINX TEST FAILED -- config NOT applied, existing sites untouched:"
    cat /tmp/ngx.err
    rm -f /etc/nginx/sites-enabled/wst.aucfans.com
    echo "Removed the wst symlink to keep nginx safe."
fi
